"use client";

import { forwardRef } from "react";
import { gridPatternDefaults, type GridPatternSpecProps } from "../generated/grid-pattern.types";
import { PatternShell, type PatternDivProps } from "../utils/pattern";

export interface GridPatternProps extends GridPatternSpecProps, Omit<PatternDivProps, keyof GridPatternSpecProps> {}

/** A grid of thin lines that fills its parent. Decoration only: hidden from assistive technology, ignores the pointer. */
export const GridPattern = forwardRef<HTMLDivElement, GridPatternProps>(function GridPattern(
  {
    size = gridPatternDefaults.size,
    strokeWidth = gridPatternDefaults.strokeWidth,
    color = gridPatternDefaults.color,
    fade = gridPatternDefaults.fade,
    animated = gridPatternDefaults.animated,
    isStill = gridPatternDefaults.isStill,
    duration = gridPatternDefaults.duration,
    ...rest
  },
  ref,
) {
  const line = (dir: string) => `linear-gradient(${dir}, var(--rdm-pc) ${strokeWidth}px, transparent ${strokeWidth}px)`;
  return (
    <PatternShell
      {...rest}
      ref={ref}
      color={color}
      fade={fade}
      animated={animated}
      isStill={isStill}
      duration={duration}
      period={size}
      travel={[size, size]}
      fill={{ backgroundImage: `${line("to right")}, ${line("to bottom")}`, backgroundSize: `${size}px ${size}px` }}
    />
  );
});

// Generated by rdloom codegen from specs/grid-pattern.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

/** A grid of thin lines that fills its parent, with an optional edge fade and a slow drift. */
export interface GridPatternSpecProps {
  /**
   * Cell size in pixels.
   * @default 32
   */
  size?: number;
  /**
   * Line thickness in pixels.
   * @default 1
   */
  strokeWidth?: number;
  /**
   * Colour of the pattern: any CSS colour or a token such as var(--rd-color-border-default).
   * @default "var(--rd-color-border-default)"
   */
  color?: string;
  /**
   * Fades the pattern out toward its edges.
   * @default true
   */
  fade?: boolean;
  /**
   * Drifts the pattern slowly, one tile per cycle. Off by default.
   * @default false
   */
  animated?: boolean;
  /**
   * Stops the drift. Moving content should be stoppable.
   * @default false
   */
  isStill?: boolean;
  /**
   * Seconds one drift cycle takes.
   * @default 10
   */
  duration?: number;
}

export const gridPatternDefaults = {
  size: 32,
  strokeWidth: 1,
  color: "var(--rd-color-border-default)",
  fade: true,
  animated: false,
  isStill: false,
  duration: 10,
} as const;

export const gridPatternMeta = {
  "name": "GridPattern",
  "version": "0.1.0",
  "status": "experimental",
  "role": "presentation"
} as const;
